begin;
create temporary table market_qa(owner_id uuid,candidate_id uuid,outsider_id uuid,job_id uuid,application_id uuid);
insert into market_qa values(gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),gen_random_uuid());
grant select on market_qa to authenticated,anon,service_role;
insert into auth.users(id,email_confirmed_at,raw_user_meta_data) select owner_id,now(),'{"full_name":"Sera QA employer"}'::jsonb from market_qa union all select candidate_id,now(),'{"full_name":"Sera QA candidate"}'::jsonb from market_qa union all select outsider_id,now(),'{"full_name":"Sera QA outsider"}'::jsonb from market_qa;
select set_config('request.jwt.claims',json_build_object('sub',(select owner_id from market_qa),'role','authenticated')::text,true);
set local role authenticated;
insert into public.jobs(id,title,company,location,work_type,description,requirements) select job_id,'QA private transaction job','QA fictional organization','Test location','Contract',repeat('Fictional role description. ',4),'Fictional testing requirements' from market_qa;
reset role;
select set_config('request.jwt.claims','{"role":"anon"}',true);
set local role anon;
do $$begin if not exists(select 1 from public.jobs where id=(select job_id from market_qa)) then raise exception 'Anonymous discovery failed';end if;begin perform * from public.applications;raise exception 'Anonymous application read allowed';exception when insufficient_privilege then null;end;begin perform * from public.email_outbox;raise exception 'Outbox exposed';exception when insufficient_privilege then null;end;end$$;
reset role;
select set_config('request.jwt.claims',json_build_object('sub',(select candidate_id from market_qa),'role','authenticated')::text,true);
set local role authenticated;
insert into public.applications(id,job_id,candidate_name,cover_note) select application_id,job_id,'QA candidate','This is a fictional test application.' from market_qa;
insert into public.saved_jobs(job_id) select job_id from market_qa;
insert into public.application_messages(application_id,body) select application_id,'Candidate test message' from market_qa;
do $$begin begin update public.applications set stage='offer' where id=(select application_id from market_qa);raise exception 'Candidate escalated stage';exception when insufficient_privilege then null;end;begin update public.jobs set employer_id=(select candidate_id from market_qa) where id=(select job_id from market_qa);raise exception 'Job ownership changed';exception when insufficient_privilege then null;end;end$$;
reset role;
select set_config('request.jwt.claims',json_build_object('sub',(select outsider_id from market_qa),'role','authenticated')::text,true);
set local role authenticated;
do $$declare n integer;begin if exists(select 1 from public.applications where id=(select application_id from market_qa)) then raise exception 'Outsider application read';end if;if exists(select 1 from public.application_messages where application_id=(select application_id from market_qa)) then raise exception 'Outsider message read';end if;update public.jobs set status='closed' where id=(select job_id from market_qa);get diagnostics n=row_count;if n<>0 then raise exception 'Outsider changed job';end if;begin insert into public.application_messages(application_id,body) select application_id,'Outsider intrusion' from market_qa;raise exception 'Outsider sent message';exception when insufficient_privilege then null;end;end$$;
reset role;
select set_config('request.jwt.claims',json_build_object('sub',(select owner_id from market_qa),'role','authenticated')::text,true);
set local role authenticated;
do $$begin if not exists(select 1 from public.applications where id=(select application_id from market_qa)) then raise exception 'Owner cannot read application';end if;end$$;
update public.applications set stage='interview' where id=(select application_id from market_qa);
insert into public.application_messages(application_id,body) select application_id,'Employer test message' from market_qa;
update public.jobs set status='closed' where id=(select job_id from market_qa);
reset role;
select set_config('request.jwt.claims',json_build_object('sub',(select outsider_id from market_qa),'role','authenticated')::text,true);
set local role authenticated;
do $$begin begin insert into public.applications(job_id,candidate_name,cover_note) select job_id,'QA outsider','This is a closed job test application.' from market_qa;raise exception 'Applied to closed job';exception when raise_exception then if sqlerrm='Applied to closed job' then raise;end if;end;end$$;
reset role;
select set_config('request.jwt.claims',json_build_object('sub',(select candidate_id from market_qa),'role','authenticated')::text,true);
set local role authenticated;
do $$begin if not exists(select 1 from public.jobs where id=(select job_id from market_qa)) then raise exception 'Applicant lost closed job';end if;end$$;
update public.applications set stage='withdrawn' where id=(select application_id from market_qa);
do $$begin begin insert into public.application_messages(application_id,body) select application_id,'Should be denied after withdrawal' from market_qa;raise exception 'Message after withdrawal allowed';exception when insufficient_privilege then null;end;end$$;
reset role;
insert into public.email_outbox(user_id) select owner_id from market_qa;
set local role service_role;
do $$begin if (select count(*) from public.claim_welcome((select owner_id from market_qa)))<>1 then raise exception 'Welcome claim failed';end if;if (select count(*) from public.claim_welcome((select owner_id from market_qa)))<>0 then raise exception 'Welcome double claim';end if;end$$;
update public.email_outbox set status='sent',sent_at=now() where user_id=(select owner_id from market_qa);
do $$begin if (select count(*) from public.claim_welcome((select owner_id from market_qa)))<>0 then raise exception 'Sent welcome claimed again';end if;end$$;
reset role;
select 'PASS: welcome queue claim and sent-record deduplication' as queue_result;
select 'PASS: candidate, employer, outsider, anonymous, ownership, stage, closure, message and outbox isolation' as result;
rollback;
